class LmdbValueRetirementRecoveryTest {

	private static final IRI PREDICATE = SimpleValueFactory.getInstance().createIRI("urn:retirement:predicate");

	@Test
	void reopenKeepsAValueReferencedByCommittedTriples(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setForceSync(true);
		IRI subject = SimpleValueFactory.getInstance().createIRI("urn:retirement:live-subject");
		TripleTerm quoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE,
						SimpleValueFactory.getInstance().createLiteral("nested live value"));
		TripleTerm nestedQuoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE, quoted);
		IRI orphan = SimpleValueFactory.getInstance().createIRI("urn:retirement:orphan-value");
		LmdbStore store = new LmdbStore(dataDir, config);
		store.init();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.addStatement(subject, PREDICATE, nestedQuoted);
			connection.commit();
		} finally {
			store.shutDown();
		}

		StoreProperties properties = new StoreProperties(dataDir);
		properties.load();
		ValueStore valueStore = new ValueStore(new File(dataDir, "values"), properties, config);
		try {
			valueStore.startTransaction(true);
			long quotedId = valueStore.getId(quoted);
			long orphanId = valueStore.getId(orphan, true);
			assertNotEquals(LmdbValue.UNKNOWN_ID, quotedId);
			assertNotEquals(LmdbValue.UNKNOWN_ID, orphanId);
			valueStore.recordRetiredIds(Set.of(quotedId, orphanId), 0);
			valueStore.commit();
			assertTrue(valueStore.hasRetiredIds(), "retirement intents must be durable before reopening");
		} finally {
			valueStore.close();
		}

		LmdbStore reopened = new LmdbStore(dataDir, config);
		reopened.init();
		try (SailConnection connection = reopened.getConnection();
				CloseableIteration<? extends Statement> statements = connection.getStatements(null, null, null,
						false)) {
			assertTrue(statements.hasNext(), "the committed statement must survive retirement recovery");
			Statement statement = statements.next();
			assertEquals(subject, statement.getSubject(),
					"recovery must recheck committed triple liveness before freeing a retired quoted value ID");
			assertEquals(nestedQuoted, statement.getObject(),
					"recursive quoted values must resolve through their preserved dictionary generation");
			assertTrue(statement.getObject().isTripleTerm());
			assertEquals(quoted, ((TripleTerm) statement.getObject()).getObject());
			assertFalse(statements.hasNext());
		} finally {
			reopened.shutDown();
		}

		ValueStore reopenedValueStore = new ValueStore(new File(dataDir, "values"), properties, config);
		try {
			assertEquals(LmdbValue.UNKNOWN_ID, reopenedValueStore.getId(orphan),
					"recovery should reclaim an orphaned retired value after the TripleStore liveness check");
		} finally {
			reopenedValueStore.close();
		}
	}

	@Test
	void failedTripleCommitPreservesLiveQuotedValuesAcrossReopen(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setForceSync(true);
		IRI subject = SimpleValueFactory.getInstance().createIRI("urn:retirement:failed-commit-subject");
		TripleTerm quoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE,
						SimpleValueFactory.getInstance().createLiteral("live nested value"));
		TripleTerm nestedQuoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE, quoted);
		IRI replacementSubject = SimpleValueFactory.getInstance().createIRI("urn:retirement:failed-replacement");
		FailingTripleCommitStore store = new FailingTripleCommitStore(dataDir, config);
		store.init();
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(subject, PREDICATE, nestedQuoted);
				connection.commit();
			}

			store.failNextTripleCommit.set(true);
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.removeStatements(subject, PREDICATE, nestedQuoted);
				connection.addStatement(replacementSubject, PREDICATE,
						SimpleValueFactory.getInstance()
								.createLiteral("dictionary addition before failed triple commit"));
				SailException failure = assertThrows(SailException.class, connection::commit);
				assertTrue(failure.getCause() instanceof IOException,
						"the injected authoritative commit error should be preserved");
			}
			assertTrue(store.getBackingStore().hasRetiredValueIds(),
					"dictionary-first failure must leave its durable retirement intent for startup revalidation");
		} finally {
			store.shutDown();
		}

		LmdbStore reopened = new LmdbStore(dataDir, config);
		reopened.init();
		try (SailConnection connection = reopened.getConnection();
				CloseableIteration<? extends Statement> statements = connection.getStatements(null, PREDICATE, null,
						false)) {
			assertTrue(statements.hasNext(), "the pre-failure committed triple must remain authoritative after reopen");
			Statement statement = statements.next();
			assertEquals(subject, statement.getSubject());
			assertEquals(nestedQuoted, statement.getObject(),
					"startup retirement recovery must preserve nested values still referenced by the failed transaction's old triples");
			assertFalse(statements.hasNext(), "the failed replacement triple must not be visible");
			assertFalse(reopened.getBackingStore().hasRetiredValueIds(),
					"recovery must finish after preserving live IDs and consuming the durable intent");
		} finally {
			reopened.shutDown();
		}
	}

	private static class FailingTripleCommitStore extends LmdbStore {

		private final AtomicBoolean failNextTripleCommit = new AtomicBoolean();
		private final AtomicBoolean dictionaryCommitted = new AtomicBoolean();

		private FailingTripleCommitStore(File dataDir, LmdbStoreConfig config) {
			super(dataDir, config);
		}

		@Override
		LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchBasedJoinEstimatorEnabled) throws IOException, SailException {
			return new LmdbSailStore(dataDir, properties, config, sketchBasedJoinEstimatorEnabled,
					(valueDir, valueProperties, valueConfig) -> new ValueStore(valueDir, valueProperties, valueConfig) {
						@Override
						public void commit() throws IOException {
							super.commit();
							if (failNextTripleCommit.get()) {
								dictionaryCommitted.set(true);
							}
						}
					},
					(tripleDir, tripleProperties, tripleConfig, valueStore) -> new TripleStore(tripleDir,
							tripleProperties, tripleConfig, valueStore) {
						@Override
						public void commit() throws IOException {
							if (failNextTripleCommit.compareAndSet(true, false)) {
								assertTrue(dictionaryCommitted.get(),
										"the authoritative TripleStore commit must follow the dictionary commit");
								throw new IOException("injected authoritative TripleStore commit failure");
							}
							super.commit();
						}
					});
		}
	}
}
